```ts
// cache.ts
type CacheEntry<T> = {
  value: T;
  expiresAt: number;
};

export class TTLCache<T> {
  private store = new Map<string, CacheEntry<T>>();

  constructor(private ttlMs: number) {}

  get(key: string): T | undefined {
    const entry = this.store.get(key);
    if (!entry) return undefined;

    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return undefined;
    }

    return entry.value;
  }

  set(key: string, value: T) {
    this.store.set(key, {
      value,
      expiresAt: Date.now() + this.ttlMs,
    });
  }

  delete(key: string) {
    this.store.delete(key);
  }
}
```

```ts
// userProfileController.ts
import { TTLCache } from "./cache";
import { getUserProfileFromDb } from "./userProfileService";

const profileCache = new TTLCache<UserProfile>(5 * 60 * 1000); // 5 min

export async function getUserProfile(req, res) {
  const userId = req.params.userId;
  const cacheKey = `user-profile:${userId}`;

  const cached = profileCache.get(cacheKey);
  if (cached) {
    res.setHeader("X-Cache", "HIT");
    return res.json(cached);
  }

  const profile = await getUserProfileFromDb(userId);

  if (!profile) {
    return res.status(404).json({ error: "User not found" });
  }

  profileCache.set(cacheKey, profile);

  res.setHeader("X-Cache", "MISS");
  return res.json(profile);
}
```

Invalidate on profile update:

```ts
export async function updateUserProfile(req, res) {
  const userId = req.params.userId;

  const updated = await updateUserProfileInDb(userId, req.body);

  profileCache.delete(`user-profile:${userId}`);

  return res.json(updated);
}
```

For multi-instance prod, use Redis instead of in-memory Map.

